## The Config Validator

You'll build a program that reads 3 hardcoded string "config values," parses them, validates ranges, and reports results — handling every possible failure gracefully.

### The Three Values

```xiom
fn main() -> Int {
  let config_max_users = "100";
  let config_port = "bad_port";
  let config_timeout = "3000";

  let r1 = validate_config("max_users", config_max_users, 1, 1000);
  let r2 = validate_config("port", config_port, 1, 65535);
  let r3 = validate_config("timeout", config_timeout, 100, 10000);

  match r1 { Ok(msg) => io.println(msg) Err(e) => io.println(e) };
  match r2 { Ok(msg) => io.println(msg) Err(e) => io.println(e) };
  match r3 { Ok(msg) => io.println(msg) Err(e) => io.println(e) };
  return 0;
}
```

### The Validation Function

```xiom
fn validate_config(name: Str, raw: Str, min: Int, max: Int) -> Result[Str, Str] {
  let parsed = string.str_to_int(raw)?;

  if parsed < min {
    return Err(name + ": value " + string.int_to_str(parsed) + " is below minimum " + string.int_to_str(min));
  }
  if parsed > max {
    return Err(name + ": value " + string.int_to_str(parsed) + " exceeds maximum " + string.int_to_str(max));
  }

  return Ok(name + " = " + string.int_to_str(parsed) + " [OK]");
}
```

### Adding a Summary Report

You can also count successes and failures:

```xiom
fn report_result(result: Result[Str, Str], ok_count: Int, fail_count: Int) -> (Int, Int) {
  return match result {
    Ok(_) => (ok_count + 1, fail_count),
    Err(_) => (ok_count, fail_count + 1),
  };
}

fn main() -> Int {
  let ok = 0;
  let fail = 0;

  let r1 = validate_config("max_users", "100", 1, 1000);
  match r1 {
    Ok(msg) => { io.println(msg); ok = ok + 1; },
    Err(e) => { io.println(e); fail = fail + 1; },
  };

  let r2 = validate_config("port", "bad_port", 1, 65535);
  match r2 {
    Ok(msg) => { io.println(msg); ok = ok + 1; },
    Err(e) => { io.println(e); fail = fail + 1; },
  };

  let r3 = validate_config("timeout", "3000", 100, 10000);
  match r3 {
    Ok(msg) => { io.println(msg); ok = ok + 1; },
    Err(e) => { io.println(e); fail = fail + 1; },
  };

  io.println("---");
  io.println("Passed: " + string.int_to_str(ok) + "/3");
  io.println("Failed: " + string.int_to_str(fail) + "/3");
  return 0;
}
```

